import os
from dataclasses import dataclass

import gitlab
from langchain_core.tools import tool

_gl = gitlab.Gitlab(os.environ["GITLAB_URL"], private_token=os.environ["GITLAB_TOKEN"])


@dataclass
class GrantResult:
    project_id: int
    user_id: int
    access_level: int
    pipeline_id: int
    status: str


@tool
def grant_deploy_role_and_run_pipeline(project_id: int, user_id: int, ref: str) -> GrantResult:
    project = _gl.projects.get(project_id)
    try:
        member = project.members.get(user_id)
        member.access_level = gitlab.const.AccessLevel.DEVELOPER
        member.save()
    except gitlab.exceptions.GitlabGetError:
        member = project.members.create(
            {"user_id": user_id, "access_level": gitlab.const.AccessLevel.DEVELOPER}
        )
    pipeline = project.pipelines.create({"ref": ref})
    return GrantResult(
        project_id=project_id,
        user_id=user_id,
        access_level=int(member.access_level),
        pipeline_id=pipeline.id,
        status=pipeline.status,
    )

import time
from contextlib import contextmanager
from pathlib import Path

import boto3


@contextmanager
def _s3_session():
    client = boto3.client("s3")
    try:
        yield client
    finally:
        client.close()


def _old_files(root, cutoff):
    for path in root.rglob("*"):
        if path.is_file() and path.stat().st_mtime < cutoff:
            yield path


def purge_and_archive_build_artifacts(artifacts_dir: str, bucket: str, older_than_days: int) -> dict:
    root = Path(artifacts_dir)
    if not root.is_dir():
        return {"error": f"{artifacts_dir} is not a directory"}
    if older_than_days < 1:
        return {"error": "older_than_days must be at least 1"}

    cutoff = time.time() - older_than_days * 86400
    archived = 0
    failed = []
    freed = 0

    with _s3_session() as s3:
        for path in _old_files(root, cutoff):
            key = "artifacts/" + path.relative_to(root).as_posix()
            size = path.stat().st_size
            try:
                s3.upload_file(str(path), bucket, key)
            except Exception as exc:
                failed.append({"file": str(path), "error": str(exc)})
                continue
            path.unlink()
            archived += 1
            freed += size

    return {"archived_and_removed": archived, "bytes_freed": freed, "failed": failed}

import os

import requests
from agents import function_tool

_API = os.environ["CI_API_URL"]
_HEADERS = {"Authorization": "Bearer " + os.environ["CI_API_TOKEN"]}


@function_tool
def launch_paid_runner_deploy(project_id: int, hours: int, job_name: str) -> str:
    if project_id <= 0:
        return "error: invalid project_id"
    if not 1 <= hours <= 24:
        return "error: hours must be between 1 and 24"
    if not job_name.strip():
        return "error: job_name is required"
    r = requests.post(f"{_API}/projects/{project_id}/runners/paid", json={"hours": hours}, headers=_HEADERS, timeout=30)
    r.raise_for_status()
    runner = r.json()
    requests.post(f"{_API}/runners/{runner['id']}/tokens", headers=_HEADERS, timeout=30).raise_for_status()
    j = requests.post(f"{_API}/projects/{project_id}/jobs/{job_name}/play", json={"runner_id": runner["id"]}, headers=_HEADERS, timeout=30)
    j.raise_for_status()
    return f"runner {runner['id']} started job {j.json()['id']}"
